function(container, apiUrl, tables) {
  // 業務ロジックモジュールをインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData, 
    collectWeatherData, 
    collectEventData, 
    collectSeasonalData, 
    analyzeCorrelationSalesWeather, 
    analyzeCorrelationSalesEvent, 
    analyzeCorrelationSalesSeason, 
    compareWithHistoricalData, 
    findAlternativeComparisonData, 
    validateComparisonPeriod 
  } = window.aivicLogic || {};

  let orderItems = [];
  let allProducts = [];
  let demandPredictions = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 明日の日付を納期の初期値に設定
  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 1);
  container.querySelector('#delivery-date').value = tomorrow.toISOString().split('T')[0];

  // 店舗データを読み込み
  function loadStores() {
    const storeSelect = container.querySelector('#store-select');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];

    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // 商品カテゴリを読み込み
  function loadCategories() {
    const categorySelect = container.querySelector('#category-select');
    const products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    const categories = [...new Set(products.map(p => p.商品カテゴリID))];

    categorySelect.innerHTML = '<option value="">全カテゴリ</option>';
    categories.forEach(categoryId => {
      if (categoryId) {
        categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId.slice(-4)}</option>`;
      }
    });
  }

  // AI予測を実行
  async function executeAIPrediction() {
    try {
      const storeId = container.querySelector('#store-select').value;
      if (!storeId) {
        window.aivicNotify.error('店舗を選択してください');
        return;
      }

      // 売上データを収集
      const salesData = await collectSalesData(storeId);

      // 商品別・店舗別に分類
      const productSalesData = classifySalesDataByProduct(salesData);
      const storeSalesData = classifySalesDataByStore(salesData);

      // 有効な商品データをフィルタリング
      const validProductData = filterValidProductData(productSalesData);

      // 外部データを収集
      const weatherData = await collectWeatherData();
      const eventData = await collectEventData();
      const seasonalData = await collectSeasonalData();

      // 相関分析を実行
      const weatherCorrelation = analyzeCorrelationSalesWeather(validProductData, weatherData);
      const eventCorrelation = analyzeCorrelationSalesEvent(validProductData, eventData);
      const seasonCorrelation = analyzeCorrelationSalesSeason(validProductData, seasonalData);

      // 履歴データと比較
      const historicalComparison = compareWithHistoricalData(validProductData);

      // 予測結果を生成（簡易実装）
      demandPredictions = validProductData.map(product => ({
        商品ID: product.商品ID,
        店舗ID: storeId,
        予測数量: Math.floor(Math.random() * 50) + 10
      }));

      renderProducts();
      window.aivicNotify.success('AI予測が完了しました');

    } catch (error) {
      console.error('AI予測エラー:', error);
      window.aivicNotify.error('AI予測の実行に失敗しました');
    }
  }

  // 商品一覧を描画
  function renderProducts(products = allProducts) {
    const tbody = container.querySelector('#product-list');
    const storeId = container.querySelector('#store-select').value;

    tbody.innerHTML = products.map(product => {
      const prediction = demandPredictions.find(p => p.商品ID === product.商品ID && p.店舗ID === storeId);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const stockQty = Math.floor(Math.random() * 100) + 10;

      return `
        <tr data-id="${product.商品ID}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>${stockQty}</td>
          <td><span class="ai-prediction">${predictedQty}</span></td>
          <td>
            <input type="number" class="input manual-qty" data-product-id="${product.商品ID}" 
                   min="0" max="9999" style="width: 80px;" placeholder="0">
          </td>
          <td>
            <button class="action-btn secondary prediction-reason-btn" data-product-id="${product.商品ID}">
              根拠表示
            </button>
          </td>
          <td>
            <button class="action-btn add-to-order-btn" data-product-id="${product.商品ID}">
              追加
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 発注一覧を描画
  function renderOrderList() {
    const tbody = container.querySelector('#order-list');
    let total = 0;

    tbody.innerHTML = orderItems.map((item, index) => {
      const subtotal = item.quantity * item.unitPrice;
      total += subtotal;

      return `
        <tr>
          <td>${item.productCode}</td>
          <td>${item.productName}</td>
          <td>¥${item.unitPrice.toLocaleString()}</td>
          <td>${item.quantity}</td>
          <td>¥${subtotal.toLocaleString()}</td>
          <td>
            <button class="action-btn danger remove-item-btn" data-index="${index}">
              削除
            </button>
          </td>
        </tr>
      `;
    }).join('');

    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 商品を発注リストに追加
  function addToOrder(productId) {
    const product = allProducts.find(p => p.商品ID === productId);
    if (!product) return;

    const manualQtyInput = container.querySelector(`input[data-product-id="${productId}"]`);
    const quantity = parseInt(manualQtyInput.value) || 0;

    if (quantity <= 0) {
      window.aivicNotify.error('数量を入力してください');
      return;
    }

    const existingIndex = orderItems.findIndex(item => item.productId === productId);
    if (existingIndex >= 0) {
      orderItems[existingIndex].quantity += quantity;
    } else {
      orderItems.push({
        productId: productId,
        productCode: product.商品コード,
        productName: product.商品名,
        unitPrice: product.単価,
        quantity: quantity
      });
    }

    manualQtyInput.value = '';
    renderOrderList();
  }

  // 発注書を保存
  async function saveOrder() {
    try {
      const storeId = container.querySelector('#store-select').value;
      const orderDate = container.querySelector('#order-date').value;
      const deliveryDate = container.querySelector('#delivery-date').value;

      if (!storeId || !orderDate || !deliveryDate || orderItems.length === 0) {
        window.aivicNotify.error('必要な項目を入力してください');
        return;
      }

      const orderData = {
        店舗ID: storeId,
        発注日: orderDate,
        納期: deliveryDate,
        発注明細: orderItems,
        合計金額: orderItems.reduce((sum, item) => sum + (item.quantity * item.unitPrice), 0)
      };

      await window.aivicApi.save('発注書', orderData);
      window.aivicNotify.success('発注書を保存しました');

      // リセット
      orderItems = [];
      renderOrderList();

    } catch (error) {
      console.error('保存エラー:', error);
      window.aivicNotify.error('発注書の保存に失敗しました');
    }
  }

  // イベントハンドラーを設定
  function setupEventHandlers() {
    // AI予測実行ボタン
    const aiPredictBtn = container.querySelector('#ai-predict-btn');
    if (aiPredictBtn) {
      aiPredictBtn.addEventListener('click', executeAIPrediction);
    }

    // 店舗選択変更
    const storeSelect = container.querySelector('#store-select');
    if (storeSelect) {
      storeSelect.addEventListener('change', () => {
        renderProducts();
      });
    }

    // カテゴリフィルター
    const categorySelect = container.querySelector('#category-select');
    if (categorySelect) {
      categorySelect.addEventListener('change', () => {
        const categoryId = categorySelect.value;
        const filteredProducts = categoryId ? 
          allProducts.filter(p => p.商品カテゴリID === categoryId) : 
          allProducts;
        renderProducts(filteredProducts);
      });
    }

    // 商品リストのイベント委譲
    const productList = container.querySelector('#product-list');
    if (productList) {
      productList.addEventListener('click', (e) => {
        if (e.target.classList.contains('add-to-order-btn')) {
          const productId = e.target.dataset.productId;
          addToOrder(productId);
        } else if (e.target.classList.contains('prediction-reason-btn')) {
          const productId = e.target.dataset.productId;
          // 予測根拠表示（モーダル等で実装）
          window.aivicNotify.info('予測根拠を表示します');
        }
      });
    }

    // 発注リストのイベント委譲
    const orderList = container.querySelector('#order-list');
    if (orderList) {
      orderList.addEventListener('click', (e) => {
        if (e.target.classList.contains('remove-item-btn')) {
          const index = parseInt(e.target.dataset.index);
          orderItems.splice(index, 1);
          renderOrderList();
        }
      });
    }

    // 発注書保存ボタン
    const saveOrderBtn = container.querySelector('#save-order-btn');
    if (saveOrderBtn) {
      saveOrderBtn.addEventListener('click', saveOrder);
    }
  }

  // 初期化処理
  async function initialize() {
    try {
      // 商品マスタを取得
      const productData = await window.aivicApi.list('商品マスタ');
      allProducts = productData.filter(p => p.有効フラグ);

      loadStores();
      loadCategories();
      renderProducts();
      renderOrderList();
      setupEventHandlers();

    } catch (error) {
      console.error('初期化エラー:', error);
      window.aivicNotify.error('画面の初期化に失敗しました');
    }
  }

  // 初期化実行
  initialize();
}
